-- =============================================================================
-- Starter articles for the Journal (News & Blog), written from Chase Care's own
-- materials. Editable or removable in the dashboard (The Journal). Also renames
-- the menu link so visitors can find it. Safe to run more than once.
-- =============================================================================

insert into public.posts (slug, title, excerpt, body, category_id, author_name, status, published_at)
select 'introducing-chase-care-services', 'Introducing CHASE Care Services', 'Who we are, what CHASE stands for, and how we provide compassionate, person-centred care in Ghana and for families abroad.', '[{"type": "paragraph", "data": {"text": "CHASE Care Services is a professional care organisation dedicated to providing compassionate, reliable and person-centred care to individuals and families — including professional care in the comfort and familiarity of their own home."}}, {"type": "paragraph", "data": {"text": "Our name is our promise: Care, Help, Assist, Support and Empower. Our mission is to ensure that every patient, child and client receives appropriate, respectful and dependable support."}}, {"type": "heading", "data": {"text": "Our core services"}}, {"type": "list", "data": {"items": ["Professional patient home care, including support after a stroke and for complex care needs", "Special needs and disability support for children and adults with autism, developmental conditions and other disabilities", "Special needs support for schools and families — after school, at weekends and in the holidays", "Nanny and childcare support for daily routines, supervision and well-being", "Companionship and personal support for everyday activities"]}}, {"type": "heading", "data": {"text": "How we care"}}, {"type": "paragraph", "data": {"text": "Quality care goes beyond meeting basic needs. Where appropriate, every package of care follows an initial assessment, an individual care plan, a risk assessment, care records and regular review, so that care is safe, coordinated and accountable."}}, {"type": "heading", "data": {"text": "Where we are"}}, {"type": "paragraph", "data": {"text": "Our offices are in Weija (Accra), Spintex Road and McCarthy Hill. Please contact us to confirm availability for your location."}}, {"type": "paragraph", "data": {"text": "At CHASE Care Services, we do not simply provide care: we build trust, preserve dignity and empower lives."}}]'::jsonb,
       (select id from public.post_categories where slug = 'community'), 'Chase Care Services', 'published', now() - interval '0 days'
where not exists (select 1 from public.posts where slug = 'introducing-chase-care-services');

insert into public.posts (slug, title, excerpt, body, category_id, author_name, status, published_at)
select 'special-educational-needs-school-partnership', 'Supporting children with special educational needs: our school partnership', 'How our trained carers work with special schools and families to give young people consistent support at school, at home and in the community.', '[{"type": "paragraph", "data": {"text": "Families supporting children and young people with special needs in Ghana often struggle to find consistent, appropriately trained and professionally minded caregivers. Our school partnership is a practical bridge to close that gap."}}, {"type": "heading", "data": {"text": "Continuity across the whole day"}}, {"type": "paragraph", "data": {"text": "Where a parent needs additional one-to-one or ongoing support, one of our carers can support the young person at school where the school agrees, and continue after school, at home and in the community. This continuity reduces disruption and gives parents confidence that their child''s needs are understood across every part of the day."}}, {"type": "heading", "data": {"text": "Our carers"}}, {"type": "paragraph", "data": {"text": "Our carers come from healthcare backgrounds, including qualified nurses and healthcare assistants, and receive additional training in special educational needs. They work within our safeguarding, professional conduct and person-centred care framework."}}, {"type": "heading", "data": {"text": "Planned around each young person"}}, {"type": "paragraph", "data": {"text": "Every placement starts with an individual assessment of the young person''s needs, strengths, routines and goals, and a support plan agreed with the parent or guardian and, where appropriate, the school. Plans are reviewed as needs change."}}, {"type": "heading", "data": {"text": "Support we offer"}}, {"type": "list", "data": {"items": ["Full-time live-in or live-out care and support", "After-school and one-to-one support", "Weekend and holiday support", "School-based support, where the school agrees", "Help with transitions between school, home and community"]}}, {"type": "paragraph", "data": {"text": "We would welcome a conversation with school leaders, SEN coordinators and families. Contact us to start a partnership."}}]'::jsonb,
       (select id from public.post_categories where slug = 'autism'), 'Chase Care Services', 'published', now() - interval '2 days'
where not exists (select 1 from public.posts where slug = 'special-educational-needs-school-partnership');

insert into public.posts (slug, title, excerpt, body, category_id, author_name, status, published_at)
select 'caring-for-a-parent-in-ghana-from-abroad', 'Caring for a parent in Ghana when you live abroad', 'Your loved one may be in Ghana while you are thousands of miles away. Here is how we help families abroad arrange trusted care.', '[{"type": "paragraph", "data": {"text": "Many families have a parent or relative in Ghana while they live and work abroad. We help families stay connected to their loved one''s care through trusted, professional services and regular communication."}}, {"type": "heading", "data": {"text": "How it works"}}, {"type": "list", "data": {"items": ["Tell us about your loved one", "We arrange a free consultation", "We agree a care plan with you", "Care begins, with regular updates to you wherever you are"]}}, {"type": "heading", "data": {"text": "What we can arrange"}}, {"type": "list", "data": {"items": ["Parent and elderly care", "Disability and autism support", "Home support and companionship", "Respite", "Hospital support", "Welfare visits", "Care coordination"]}}, {"type": "paragraph", "data": {"text": "We care for families with loved ones back home in Ghana, Nigeria and Dubai. Request care online, or call or WhatsApp us to talk it through."}}]'::jsonb,
       (select id from public.post_categories where slug = 'elderly-care'), 'Chase Care Services', 'published', now() - interval '5 days'
where not exists (select 1 from public.posts where slug = 'caring-for-a-parent-in-ghana-from-abroad');

update public.navigation_items set label = 'News & Blog' where menu = 'main' and href = '/journal' and label = 'The ChaseCare Journal';
